const fs = require('fs');
const path = require('path');

// This script reads a file containing the links generated by Up-4Ever or FileUpload.
// It assumes the original filename (e.g. chs001.pdf) is preserved in the URL or page.
// Usage: node link-ppd-urls.js <provider> <input-file.txt>
// Example: node link-ppd-urls.js up4ever up4ever-links.txt

function linkUrls() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.error('Usage: node link-ppd-urls.js <provider> <input-file.txt>');
    console.error('provider: up4ever OR fileupload');
    process.exit(1);
  }

  const provider = args[0];
  const inputFile = args[1];

  const inputPath = path.join(process.cwd(), inputFile);
  const dbPath = path.join(process.cwd(), '../lib/sermon_downloads.json');

  if (!fs.existsSync(inputPath)) {
    console.error(`Input file not found: ${inputPath}`);
    process.exit(1);
  }

  const links = fs.readFileSync(inputPath, 'utf8').split('\n').filter(Boolean);
  
  let db = {};
  if (fs.existsSync(dbPath)) {
    db = JSON.parse(fs.readFileSync(dbPath, 'utf8'));
  }

  let matchedCount = 0;

  for (const link of links) {
    // Attempt to find the sermon number in the link.
    // e.g., https://up-4ever.net/xyz123/chs001.pdf
    const match = link.match(/chs0*(\d+)/i);
    if (match) {
      const sermonNum = match[1];
      // We need to know which volume it belongs to.
      // Assuming 50-60 sermons per volume, we can roughly estimate, but ideally we'd map this using the sermons structure.
      // For a robust implementation, this script should load the sermon index or search for the sermon-num across volumes.
      // This is a simplified version. You will need to import your sermon metadata to find the exact volumeId.
      
      console.log(`Matched Sermon ${sermonNum} -> ${link.trim()}`);
      
      // Placeholder: You'll need to lookup the volume ID for this sermon.
      // const volumeId = findVolumeForSermon(sermonNum); 
      // db[`${volumeId}::sermon-${sermonNum}`] = { ...db[`${volumeId}::sermon-${sermonNum}`], [provider]: link.trim() };
      
      matchedCount++;
    }
  }

  // fs.writeFileSync(dbPath, JSON.stringify(db, null, 2));
  console.log(`Processed ${links.length} links, successfully matched ${matchedCount} to sermons.`);
  console.log(`Update logic to match volume ID is needed before saving to sermon_downloads.json.`);
}

linkUrls();
